export async function requestCalendarPermissionsAsync(){return {status:'granted',granted:true}}
export async function createEventInCalendarAsync(event:any){const clean=(date:any)=>new Date(date).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const ics=`BEGIN:VCALENDAR\nVERSION:2.0\nBEGIN:VEVENT\nSUMMARY:${event.title||''}\nDTSTART:${clean(event.startDate)}\nDTEND:${clean(event.endDate)}\nLOCATION:${event.location||''}\nDESCRIPTION:${event.notes||''}\nEND:VEVENT\nEND:VCALENDAR`;const url=URL.createObjectURL(new Blob([ics],{type:'text/calendar'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='cda-event.ics';anchor.click();URL.revokeObjectURL(url)}
